function ParkourBossMainRankRewardDialog:InitData()
    ---@type Engine.UI.UIArgument
    local argument = self.controller.Argument
    local t = checkTable(argument.parameters)
    if checkInt(t.rankType) == 1 then
        self._rewardsList = CfUtils.GetCf(AutoIds.IdSetting6455, "ActivityCakeBossRankVo", true)
    else
        self._rewardsList = CfUtils.GetCf(AutoIds.IdSetting6466, "ActivityCakeBossRankVo", true)
